# Count unique adjacent pairs to detect patterns
def count_horizontal_transitions(grid):
    """Count positions where row differs from below it"""
    h, w = len(grid), len(grid[0])
    changes = 0
    for i in range(h-1):
        for j in range(w):
            if grid[i][j] != grid[i+1][j]:
                changes += 1
    return changes

def analyze_patterns(grid, name):
    counts = {}
    for row in grid:
        for val in row:
            counts[val] = counts.get(val, 0) + 1

    print(f"\n{name}:")
    print(f"  Dimensions: {len(grid)}x{len(grid[0])}")
    print(f"  Color frequencies: {counts}")
    print(f"  Horizontal transitions: {count_horizontal_transitions(grid)}")

    # Check if rows are mostly uniform
    for i, row in enumerate(grid[:5]):
        unique = set(row)
        print(f"  Row {i}: {unique}, transition_count={sum(1 for j in range(len(row)-1) if row[j]!=row[j+1])}")

